<?php
/** Proof — recurring templates (spec "Proof" 1): journal / bill / invoice templates, Run now, the worker's step, a failed run, the end date, validation, who may. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $bea = as_member(27); $vera = as_member(26);
ensure_year($owner); $fx = ar_fixture();
$vendor = mk_vendor('SMOKE Landlord'); $cust = mk_customer('SMOKE Tenant Co');
$e = post_entry('2026-10-01', [['6200', '1200.00', '0.00'], ['1010', '0.00', '1200.00']], 'SMOKE monthly rent');
echo "1. A journal template from an existing entry\n";
[$c, $b] = screen($owner, '/settings/recurring/new?from=journal:' . $e);
ok($c === 200 && ($b['prefill']['kind'] ?? '') === 'journal' && count($b['prefill']['template']['lines'] ?? []) === 2 && ($b['prefill']['template']['lines'][0]['account'] ?? 0) === account_id('6200'), 'the add screen copies the entry into a prefill (kind, two lines, accounts as ids)');
[$c, $b, $jid] = mk_template('journal', 'SMOKE Rent journal', $b['prefill']['template']);
ok($c === 200 && $jid > 0 && tpl_row($jid)['next_date'] === '2026-11-01' && tpl_row($jid)['active'], 'saved: ok, next date 2026-11-01, on');
ok(count(activity('recurring.save', 0)) >= 1, 'logged recurring.save');
$before = (int) one('SELECT count(*) FROM journal_entries');
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $jid]);
$draft = (int) ($b['record_id'] ?? 0);
$row = q('SELECT * FROM journal_entries WHERE id = :i', ['i' => $draft])[0] ?? [];
ok($c === 200 && $draft > 0 && $row['status'] === 'draft' && $row['entry_date'] === '2026-11-01' && $row['source'] === 'recurring' && (int) one('SELECT count(*) FROM journal_lines WHERE entry_id = :e', ['e' => $draft]) === 2, 'Run now (the Bookkeeper) drafts an entry dated the run date, source recurring, with the two lines — a DRAFT');
ok(tpl_row($jid)['next_date'] === '2026-12-01' && (int) tpl_row($jid)['run_count'] === 1 && one("SELECT status FROM recurring_runs WHERE template_id = :t AND run_date = '2026-11-01'", ['t' => $jid]) === 'drafted', 'the schedule moved to 2026-12-01 and the run is recorded as drafted');
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $jid, 'run_date' => '2026-11-01']);
ok($c === 422 && str_contains(msg($b), 'already drafted'), 'the same date twice is refused in words (' . msg($b) . ')');
echo "2. The worker's step: when due, not before\n";
$r = worker(['--only=recurring'], '2026-11-30');
ok(($r['results']['recurring']['drafted'] ?? -1) === 0, 'not due on 2026-11-30: nothing drafted');
$r = worker(['--only=recurring'], '2026-12-01');
ok(($r['results']['recurring']['drafted'] ?? 0) === 1 && tpl_row($jid)['next_date'] === '2027-01-01', 'due on 2026-12-01: drafted once, now 2027-01-01 (' . json_encode($r['results'] ?? $r) . ')');
$cron = q("SELECT * FROM activity_log WHERE action = 'recurring.run' ORDER BY id DESC LIMIT 1")[0];
ok($cron['source'] === 'cron' && $cron['actor_member_id'] === null && json_decode((string) $cron['after'], true)['status'] === 'drafted', 'logged recurring.run with source cron, no actor');
echo "3. A failed run advances nothing\n";
$acct = (int) one("INSERT INTO accounts (code, name, account_type, subtype, is_bank, is_control, is_system) VALUES ('6998', 'SMOKE short-lived', 'expense', 'other', false, false, false) RETURNING id");
[$c, $b, $fid] = mk_template('journal', 'SMOKE Fragile', ['memo' => 'fragile', 'lines' => [['account' => '6998', 'debit' => '10.00'], ['account' => '1010', 'credit' => '10.00']]]);
ok($c === 200 && $fid > 0, 'a template naming a fresh account saves');
q('UPDATE accounts SET archived_at = now() WHERE id = :a', ['a' => $acct]);
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $fid]);
ok($c === 422 && str_contains(msg($b), 'Line 1'), 'Run now on a template whose account was archived: 422 naming the line (' . msg($b) . ')');
ok(tpl_row($fid)['next_date'] === '2026-11-01' && (int) tpl_row($fid)['run_count'] === 0 && one("SELECT status FROM recurring_runs WHERE template_id = :t", ['t' => $fid]) === 'failed', 'nothing advanced; the run is recorded as failed with the sentence');
[$cc, $card] = screen($owner, '/settings/recurring/');
$mine = array_values(array_filter($card['templates'] ?? [], fn ($t) => $t['name'] === 'SMOKE Fragile'))[0] ?? [];
ok(($mine['last_status'] ?? '') === 'failed' && str_contains((string) ($mine['last_detail'] ?? ''), 'Line 1'), 'the list says "last run failed: …"');
echo "4. A bill and an invoice\n";
[$c, $b, $bid] = mk_template('bill', 'SMOKE Rent bill', ['vendor' => $vendor, 'vendor_ref_pattern' => 'RENT-{YYYY-MM}', 'terms_days' => 10, 'memo' => 'Rent', 'lines' => [['description' => 'Office rent', 'quantity' => '1', 'unit_price' => '1200.00', 'expense_account' => '6200']]]);
ok($c === 200 && $bid > 0, 'a bill template saves (vendor by id)');
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $bid]);
$bill = q('SELECT * FROM bills WHERE id = :i', ['i' => (int) ($b['record_id'] ?? 0)])[0] ?? [];
ok($c === 200 && $bill['vendor_ref'] === 'RENT-2026-11' && $bill['status'] === 'draft' && $bill['source'] === 'recurring' && $bill['due_date'] === '2026-11-11' && $bill['total'] === '1200.00', 'the bill is a draft with vendor ref RENT-2026-11, due in 10 days, 1,200.00');
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $bid]);
ok($c === 200 && (q('SELECT vendor_ref FROM bills ORDER BY id DESC LIMIT 1')[0]['vendor_ref'] ?? '') === 'RENT-2026-12', 'the next run is RENT-2026-12');
[$c, $b, $iid] = mk_template('invoice', 'SMOKE Retainer', ['customer' => $cust, 'reference_pattern' => 'Retainer {MON} {YYYY}', 'lines' => [['description' => 'Monthly retainer', 'quantity' => '1', 'unit_price' => '2500.00', 'income_account' => '4100']]], ['next_date' => '2026-11-15', 'end_date' => '2026-12-31', 'cadence' => 'monthly']);
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $iid]);
$inv = q('SELECT * FROM invoices WHERE id = :i', ['i' => (int) ($b['record_id'] ?? 0)])[0] ?? [];
ok($c === 200 && $inv['status'] === 'draft' && $inv['reference'] === 'Retainer Nov 2026' && $inv['issue_date'] === '2026-11-15' && $inv['total'] === '2500.00', 'the invoice is a draft with reference "Retainer Nov 2026", 2,500.00');
ok(tpl_row($iid)['next_date'] === '2026-12-15' && tpl_row($iid)['active'], 'next 2026-12-15, still on');
[$c, $b] = act($bea, '/settings/recurring/run.php', ['template' => $iid]);
ok($c === 200 && !tpl_row($iid)['active'] && tpl_row($iid)['next_date'] === '2027-01-15', 'the run that passes the end date turns the template off (db/019: the check no longer refuses it)');
echo "5. Validation, rights, toggle, delete\n";
[$c, $b] = mk_template('journal', 'SMOKE Unbalanced', ['lines' => [['account' => '6200', 'debit' => '10.00'], ['account' => '1010', 'credit' => '9.00']]]);
ok($c === 422 && str_contains(msg($b), 'do not balance'), 'unbalanced lines refused: ' . msg($b));
[$c, $b] = mk_template('journal', 'SMOKE Odd key', ['flavour' => 'x', 'lines' => [['account' => '6200', 'debit' => '1.00'], ['account' => '1010', 'credit' => '1.00']]]);
ok($c === 422 && str_contains(msg($b), 'flavour'), 'an unknown key refused by name');
[$c, $b] = mk_template('journal', 'SMOKE Bad line', ['lines' => [['account' => '6200', 'debit' => '1.00', 'credit' => '1.00']]]);
ok($c === 422 && str_contains(msg($b), 'Line 1'), 'a bad line names its number: ' . msg($b));
[$c, $b] = act($owner, '/settings/recurring/save.php', ['template' => $jid, 'kind' => 'bill', 'name' => 'SMOKE Rent journal']);
ok($c === 422 && isset(fields($b)['kind']), 'the kind is fixed once made');
[$c, $b] = act($bea, '/settings/recurring/save.php', ['name' => 'SMOKE By Bea', 'kind' => 'journal', 'next_date' => '2026-11-01', 'template' => '{}']);
ok($c === 403, 'the Bookkeeper cannot save a template (settings.manage): ' . $c);
[$c, $b] = act($vera, '/settings/recurring/run.php', ['template' => $jid]);
ok($c === 403, 'a Viewer cannot run one');
ok(screen($bea, '/settings/recurring/')[0] === 403, 'the list is for settings.manage only');
[$c, $b] = act($owner, '/settings/recurring/toggle.php', ['template' => $jid, 'active' => 'no']);
ok($c === 200 && !tpl_row($jid)['active'], 'toggled off');
$runsBefore = (int) one('SELECT count(*) FROM recurring_runs WHERE template_id = :t', ['t' => $jid]);
$r = worker(['--only=recurring'], '2027-06-01');
ok((int) one('SELECT count(*) FROM recurring_runs WHERE template_id = :t', ['t' => $jid]) === $runsBefore && $r['errors'] === [], 'an off template is skipped by the worker (the other templates that are due may run)');
ok((int) one("SELECT count(*) FROM recurring_runs WHERE template_id = :t AND run_date > '2026-12-01'", ['t' => $jid]) === 0, 'and drafts nothing');
$runs = (int) one('SELECT count(*) FROM recurring_runs WHERE template_id = :t', ['t' => $jid]);
[$c, $b] = act($owner, '/settings/recurring/toggle.php', ['template' => $jid, 'active' => 'yes']);
[$c2, $b2] = act($owner, '/settings/recurring/save.php', ['name' => 'SMOKE Rent journal', 'kind' => 'journal', 'next_date' => '2027-01-01', 'template' => json_encode(['lines' => [['account' => '6200', 'debit' => '1.00'], ['account' => '1010', 'credit' => '1.00']]])]);
ok($c === 200 && $c2 === 422 && str_contains(msg($b2), 'active template named'), 'two ON templates of one name are refused');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/recurring/delete.php', ['template' => $jid]);
ok($c === 200 && !tpl_row($jid) && (int) one('SELECT count(*) FROM recurring_runs WHERE template_id = :t', ['t' => $jid]) === 0, 'deleted with its runs');
ok($e > 0 && (int) one("SELECT count(*) FROM journal_entries WHERE source = 'recurring'") >= 2, 'the drafts it made stay');
$rows = activity('recurring.delete', $since);
ok(count($rows) === 1 && json_decode((string) $rows[0]['before'], true)['name'] === 'SMOKE Rent journal', 'logged recurring.delete with the template as it was');
finish();
